function plot_results(results)

% =========================================================================
% Visualization function
%
% Description:
%   Plot neutrophil dynamics from cycles 16 to 19.
%
% Input:
%   results - Simulation results generated by run_model.m
%
% =========================================================================

%% 1. Create output directory
if ~exist('Results', 'dir')
    mkdir('Results');
end

parameter_index = results.parameter_index;

%% 2. Plot neutrophil dynamics

figure('Color', 'w', 'Position', [100, 100, 900, 450]);

plot(results.T, results.Y(3, :), '-', ...
    'LineWidth', 2, ...
    'Color', [150 54 52]./255);

hold on;

scatter(results.exp_data, results.y_pred, ...
    'o', 'filled', ...
    'MarkerEdgeColor', [255, 255, 255]./255, ...
    'MarkerFaceColor', [122, 46, 56]./255, ...
    'SizeData', 100);

%--------------------------------------------------------------------------
% Legend
%--------------------------------------------------------------------------
leg = legend('Model curve',' Data',...
    'Location','north','Orientation','horizontal','NumColumns', 5);
set(leg,'EdgeColor',[0.65 0.65 0.65],'FontName','Arial','FontSize',16);

%--------------------------------------------------------------------------
% Axes formatting (log scale)
%--------------------------------------------------------------------------
ax = gca;
box on;
set(ax, 'YScale', 'log');
xlim(ax, [results.T(1), results.T(end)]);
ylim(ax, [1e-1,250]);
yticks(ax, [0.1, 1, 10, 100]);
yticklabels(ax, {'0.1', '1', '10', '100'});

set(ax, ...
    'YMinorTick', 'off', ...
    'XMinorTick', 'off', ...
    'GridLineStyle', '-', ...
    'GridAlpha', 0.3, ...
    'GridColor', [0.8,0.8,0.8], ...
    'MinorGridLineStyle', 'none');
grid(ax, 'on');

set(gca,'FontName','Arial', 'FontSize', 16,'LineWidth', 1.5);
xlabel('Time (days)','FontName','Arial','FontSize',16);
ylabel({'Circulating neutrophil (10^8 cells/kg)'},'FontName','Arial','FontSize',16);

hold off;

%% 3. Save figure
filename = sprintf('simulation_results_%d.jpg', ...
    parameter_index);

exportgraphics(gcf, ...
    fullfile('Results', filename), ...
    'Resolution', 600, ...
    'BackgroundColor', 'white');

fprintf('Figure saved: %s\n', filename);

hold(ax, 'off');

end
